    # currently present letters and can never restore it to 26.
    if edges > 0 and len(set(t)) == 26:
        print(-1)
        return

    state = [0] * 26  # 0: unvisited, 1: visiting, 2: finished
    cycles = 0

    def dfs(v):
        nonlocal cycles
        state[v] = 1

        nxt = to[v]
        if nxt != -1 and nxt != v:
            if state[nxt] == 0:
                dfs(nxt)
            elif state[nxt] == 1:
                cycles += 1

        state[v] = 2

    for v in range(26):
        if to[v] != -1 and to[v] != v and state[v] == 0:
            dfs(v)

    print(edges + cycles)

