class FenwickMax:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def update(self, i, value):
        n = self.n
        while i <= n:
            if value > self.bit[i]:
                self.bit[i] = value
            i += i & -i

    def query(self, i):
        result = 0
        while i > 0:
            if self.bit[i] > result:
                result = self.bit[i]
            i -= i & -i
        return result


