from bisect import bisect_left

def build_path_and_check(n, x, initial, perm):
    inv = [0] * (n + 1)
    for i in range(1, n + 1):
        inv[perm[i]] = i

    dist = [-1] * (n + 1)
    node_at_dist = [x]
    dist[x] = 0

    cur = x
    d = 0
    while True:
        cur = inv[cur]
        if cur == x:
            break
        d += 1
        dist[cur] = d
        node_at_dist.append(cur)

    farthest = 0
    for i in range(1, n + 1):
        if initial[i]:
            if dist[i] == -1:
                return None
            if dist[i] > farthest:
                farthest = dist[i]

    path = []
    if farthest > 0:
        cur = node_at_dist[farthest]
        while cur != x:
            path.append(cur)
            cur = perm[cur]

    return path

