    p = [0] + [next(it) for _ in range(n)]
    q = [0] + [next(it) for _ in range(n)]

    red_path = build_path_and_check(n, x, a, p)
    blue_path = build_path_and_check(n, x, b, q)

    if red_path is None or blue_path is None:
