    lis = []

    for v in red_path:
        if v in pos_blue:
            z = pos_blue[v]
            k = bisect_left(lis, z)
            if k == len(lis):
                lis.append(z)
            else:
                lis[k] = z

    lcs = len(lis)
    print(len(red_path) + len(blue_path) - lcs)

