from typing import List


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        eligible = [x for x in nums if x <= threshold]
        isolated = len(nums) - len(eligible)

        parent = list(range(len(eligible)))
        size = [1] * len(eligible)

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        owner = [-1] * (threshold + 1)

        for i, value in enumerate(eligible):
            for multiple in range(value, threshold + 1, value):
                if owner[multiple] == -1:
                    owner[multiple] = i
                else:
                    union(i, owner[multiple])

        return len({find(i) for i in range(len(eligible))}) + isolated
